@pytest.mark.parametrize("name", sorted(EXPECTED["v80"]))
def test_v80_matches_track0(world: SimpleNamespace, name: str) -> None:
    result = _run(world, world.new[name], f"demo.cf.t1.v80.{name}")
    expected = EXPECTED["v80"][name]
    if name in REJECTED:
        assert result.get("error") == "FindingModelError", result
        assert REJECTED[name] in str(result.get("message"))
        return
    assert result.get("error") is None, result.get("message")
    _assert_sound(name, result)
    assert world.cfp.check(name, result) == {}
    assert _projection(result) == expected


@pytest.mark.parametrize("name", sorted(EXPECTED["carried"]))
def test_v79_returns_on_v80_under_the_new_no(world: SimpleNamespace, name: str) -> None:
    result = _run(world, world.carried[name], f"demo.cf.t1.c80.{name}")
    expected = EXPECTED["carried"][name]
    if expected["error"] is not None:
        assert result.get("error") == expected["error"], result
        return
    assert result.get("error") is None, result.get("message")
    _assert_sound(name, result)
    assert _projection(result) == expected["v80"]
    lines = result["lines"]
    v80_form1040 = [lines["form1040.line-15"][1], lines["form1040.line-16"][1]]
    if name in ACCEPTED_BLOCKS:
        assert None not in expected["v79_form1040"]
        assert lines["form1040.line-15"][0] == lines["form1040.line-16"][0] == "blocked"
    else:
        assert v80_form1040 == expected["v79_form1040"]


def test_boundary_no_without_member_now_blocks_without_a_false_lead() -> None:
    """Decision 2: a Form 8949 "no" that no answer admits is no longer the wage return.

    The new in-class answer cannot admit it (the no-Form-1099-B answer is no),
    so the page does not ask it (review S1 and N2). Lines 3 and 10 show their
    blocked text, the Decision 4 and 6 limit.
    """
    case = EXPECTED["carried"]["boundary_no_without_member"]
    assert case["v79_form1040"] == [34250, 3875]
    assert case["v80"]["lines"]["form1040.line-15"] == ["blocked", None]
    assert case["v80"]["attachments"] == {"f8949": "blocked", "schedule-d": "blocked"}
    assert IN_CLASS_QUESTION not in case["v80"]["questions"]
    assert case["v80"]["rows"]["schedule-d-line3"] == ["blocked", "DEPENDENCY_ABSENT", []]


def test_the_in_class_question_is_asked_where_it_can_admit_the_return() -> None:
    case = EXPECTED["v80"]["f_gain_new_ic_unanswered"]
    assert case["lines"]["schedule-d.line-10"] == ["blocked", None]
    assert IN_CLASS_QUESTION in case["questions"]


@pytest.mark.parametrize("name, line", [
    ("c_code_w_on_gain", "schedule-d.line-10"),
    ("f_holding_mismatch", "schedule-d.line-3"),
])
def test_a_failing_sale_does_not_block_the_other_term_line(name: str, line: str) -> None:
    """Review S1: the other term's line counts the sales, so a failing subtotal is not read."""
    case = EXPECTED["v80"][name]
    assert case["lines"][line] == ["computed_zero", 0]
    assert case["lines"]["form1040.line-15"] == ["blocked", None]


def test_one_sale_recorded_as_box_c_and_box_f_blocks() -> None:
    """Review S2: the two facts share the sale key, so each term's amount check disagrees."""
    case = EXPECTED["v80"]["c_and_f_same_sale"]
    assert case["lines"]["schedule-d.line-3"] == case["lines"]["schedule-d.line-10"] == ["blocked", None]
    assert case["lines"]["form1040.line-15"] == ["blocked", None]
    assert case["attachments"] == {"f8949": "blocked", "schedule-d": "blocked"}
    for term in ("st", "lt"):
        assert case["rows"][f"f8949.no1099b-{term}-txn.amounts-check"] == ["blocked", "DEPENDENCY_INVALID", []]


def test_a_late_sale_after_yes_beside_the_other_term_blocks_without_a_question() -> None:
    """The limit review S2's fix brings, pinned as it behaves.

    A box C sale recorded after a "yes" that a box F sale backs leaves the box C
    families unconfirmed. Each box F sale's amount check now counts the box C
    sales for the same sale, so it blocks on that closure, and the page cannot
    trace a per-sale check to its closure question. Both lines show their
    blocked text, which names the no-Form-1099-B answer; the Form 1040 blocks.
    """
    case = EXPECTED["v80"]["q2_late_yes_stale"]
    assert case["lines"]["schedule-d.line-3"] == case["lines"]["schedule-d.line-10"] == ["blocked", None]
    assert case["lines"]["form1040.line-15"] == ["blocked", None]
    assert case["questions"] == []
    assert EXPECTED["v80"]["q2_late_yes_reanswered"]["lines"]["form1040.line-15"][0] == "published_value"


@pytest.mark.parametrize("name, line, value", [
    ("c_loss_path_b_unanswered", "schedule-d.line-3", -6000),
    ("f_gain_path_b_unanswered", "schedule-d.line-10", 4000),
])
def test_path_b_unanswered_blocks_the_return_but_not_lines_3_and_10(name: str, line: str, value: int) -> None:
    """Review S4, pinned as it behaves.

    The admission arm the no-Form-1099-B and new in-class answers satisfy is
    read before the ADR-0061 Path B answer, so lines 3 and 10 compute. The
    preferential base and both attachments require Path B by their own
    dependency set whenever Schedule D has activity and Form 8949 is answered
    no, so line 7a and the Form 1040 block, with no question: the ADR-0061
    pair has no input question, as on v79. Recorded as a limit.
    """
    case = EXPECTED["v80"][name]
    assert case["lines"][line] == ["published_value", value]
    assert case["lines"]["schedule-d.line-16"] == ["published_value", -6000 if value < 0 else 4000]
    assert case["lines"]["form1040.line-7a"] == case["lines"]["form1040.line-15"] == ["blocked", None]
    assert case["attachments"] == {"f8949": "blocked", "schedule-d": "blocked"}
    assert case["questions"] == []


def test_the_new_question_is_asked_when_unanswered() -> None:
    case = EXPECTED["v80"]["wage_q2_unanswered"]
    assert case["lines"]["form1040.line-15"] == ["blocked", None]
    assert Q2_QUESTION in case["questions"]


def test_expectation_table_covers_every_track0_case() -> None:
    # The 71 Track 0 cases, plus c_and_f_same_sale (review S2) and the two
    # Path B unanswered cases (review S4).
    assert len(EXPECTED["v80"]) + len(DUPLICATES) == 74
    for duplicate, kept in DUPLICATES.items():
        assert duplicate not in EXPECTED["v80"] and kept in EXPECTED["v80"]
    assert len(EXPECTED["carried"]) == 50
    assert set(ACCEPTED_BLOCKS) <= set(EXPECTED["carried"])
    assert set(REJECTED) <= set(EXPECTED["v80"])
